member.remarks:
Requets example:
GET /api/accounts
-H "Authorization: Bearer YOUR_ACCESS_TOKEN"

Response example:
{
    "accounts": [    
                {
                    "id": "30dd879c-ee2f-11db-8314-0800200c9a66",
                    "balance": 300,
                    "user_id": "3b7c138f-fc68-42b8-a705-31417bb4cb56"
                },
                ...
             ]
    
}

Request example:
POST /api/auth/token
{
    "login": "mylogin",
    "password": "mypassword"
}

Response example:
{
    "access_token": "eyJ...",
    "refresh_token": "...",
    "expires_in": 900
}

OR

Response example:
{
    "message": "verific ation code was sent to your email"
    "challenge_token": "eyJ...",
    "expires_in": 90,
    "_links": {
         "verify": {
            "href": "/api/auth/2fa/complete",
            "method": "POST",
            "title": "verification code confirmation"
         },
         "resend": {
            "href": "/api/auth/2fa/resend",
            "method": "POST",
            "title": "resend verification code"
         }
    }
}

Request example:
POST /api/auth/2fa/complete
-H "Authorization: Bearer YOUR_CHALLENGE_TOKEN"
{
    "code": 123456
}

Response example:
{
    "access_token": "eyJ...",
    "refresh_token": "...",
    "expires_in": 900
}

Request example:
POST /api/auth/2fa/resend
-H "Authorization: Bearer YOUR_CHALLENGE_TOKEN"

Response example:
{
    "message": "verification code was sent to your email"
    "challenge_token": "eyJ...",
    "expires_in": 90,
    "_links": {
         "verify": {
            "href": "/api/auth/2fa/complete",
            "method": "POST",
            "title": "verification code confirmation"
         },
         "resend": {
            "href": "/api/auth/2fa/resend",
            "method": "POST",
            "title": "resend verification code"
         }
    }
}

Request example:
POST /api/auth/token/refresh
{
    "refresh_token": "..." 
}

Response example:
{
    "access_token": "eyJ...",
    "refresh_token": "...",
    "expires_in": 900
}

Request example:
POST /api/auth/token/revoke
-H "Authorization: Bearer YOUR_ACCESS_TOKEN"
{
    "refresh_token": "YOUR_REFRESH_TOKEN"
}

Request example:
POST /api/transactions
-H "Authorization: Bearer YOUR_ACCESS_TOKEN"
{
    "amount": "300",
    "source_account_id": "30dd879c-ee2f-11db-8314-0800200c9a66",
    "destination_account_id": "3b7c138f-fc68-42b8-a705-31417bb4cb56",
}

Response example:
{
    "id": "CREATED_Transaction_ID"
}

